void VdSetGraphicsInterruptCallback_entry(function_t callback,
                                          lpvoid_t user_data) {
  // callback takes 2 params
  // r3 = bool 0/1 - 0 is normal interrupt, 1 is some acquire/lock mumble
  // r4 = user_data (r4 of VdSetGraphicsInterruptCallback)
  // Phase 636: the CP blocks on a memory fence xam expects an interrupt
  // handler to write, and Xenia dispatches PM4_INTERRUPT to whichever
  // callback was registered last. Record every registration with its caller
  // so a title-owned callback serving xam's interrupts is visible.
  {
    uint32_t lr = 0;
    if (auto* th = XThread::GetCurrentThread()) {
      lr = static_cast<uint32_t>(th->thread_state()->context()->lr);
    }
    XELOGI("VdSetGraphicsInterruptCallback: cb={:08X} data={:08X} from "
           "lr={:08X}",
           uint32_t(callback), user_data.guest_address(), lr);
  }
  auto graphics_system = kernel_state()->emulator()->graphics_system();
  graphics_system->SetInterruptCallback(callback, user_data);
}
DECLARE_XBOXKRNL_EXPORT1(VdSetGraphicsInterruptCallback, kVideo, kImplemented);

static void RecordGuideRingBuffer(uint32_t ptr);  // defined by VdPersistDisplay

void VdInitializeRingBuffer_entry(lpvoid_t ptr, int_t size_log2) {
  // r3 = result of MmGetPhysicalAddress
  // r4 = log2(size)
  // Buffer pointers are from MmAllocatePhysicalMemory with WRITE_COMBINE.
  // Phase 607: this had no logging, so "the ring never moves" (phase 595) was
  // known only from polling the command processor's state. Record every call
  // with its caller, so which module installs the live ring - and whether xam
  // ever tries - is a matter of record rather than inference.
  {
    uint32_t lr = 0;
    if (auto* th = XThread::GetCurrentThread()) {
      lr = static_cast<uint32_t>(th->thread_state()->context()->lr);
    }
    XELOGI("VdInitializeRingBuffer(ptr={:08X}, size_log2={}) from lr={:08X}",
           ptr.guest_address(), int32_t(size_log2), lr);
    RecordGuideRingBuffer(ptr.guest_address());
    // Phase 639: the mode-1 device owns this ring, its fence and the
    // submitted/completed counters the interrupt service reads - and the
    // 81A0FE48 breakpoint that was supposed to capture it never fires. It is
    // live in a register here. Dump the heap-pointer-shaped ones.
    if (auto* th2 = XThread::GetCurrentThread()) {
      auto* c = th2->thread_state()->context();
      std::string regs;
      for (int r = 3; r <= 31; ++r) {
        uint32_t v = static_cast<uint32_t>(c->r[r]);
        if ((v & 0xFF000000u) == 0x40000000u) {
          regs += fmt::format("r{}={:08X} ", r, v);
        }
      }
      XELOGI("VdInitRing regs: {}", regs);
      // Phase 640: this is the one place the mode-1 device is provably live.
      // The 81A0FE48 breakpoint that was meant to capture it never fires, so
      // guide_mode1_device_ has been zero for every phase that wanted it
      // (616, 630, 631). r31 holds the device across this call, and a ring
      // initialised from xam (lr in 0x81xxxxxx) is by definition mode 1's.
      uint32_t dev_r31 = static_cast<uint32_t>(c->r[31]);
      if ((lr >> 24) == 0x81u && (dev_r31 & 0xFF000000u) == 0x40000000u) {
        GuideSetMode1Device(dev_r31);
        XELOGI("VdInitRing: captured mode-1 device {:08X}", dev_r31);
      }
    }
  }
  auto graphics_system = kernel_state()->emulator()->graphics_system();
  graphics_system->InitializeRingBuffer(ptr, size_log2);
}
DECLARE_XBOXKRNL_EXPORT1(VdInitializeRingBuffer, kVideo, kImplemented);

void VdEnableRingBufferRPtrWriteBack_entry(lpvoid_t ptr,
                                           int_t block_size_log2) {
  // r4 = log2(block size), 6, usually --- <=19
  auto graphics_system = kernel_state()->emulator()->graphics_system();
  graphics_system->EnableReadPointerWriteBack(ptr, block_size_log2);
}
DECLARE_XBOXKRNL_EXPORT1(VdEnableRingBufferRPtrWriteBack, kVideo, kImplemented);

void VdGetSystemCommandBuffer_entry(lpunknown_t p0_ptr, lpunknown_t p1_ptr,
                                    const ppc_context_t& context) {
  {
    // Who is actually calling this 600,000 times? A back-edge analysis
    // named a loop that runs 36 times, so ask the caller directly
    // instead of reasoning about control flow.
    static std::atomic<uint32_t> lrn{0};
    static std::mutex lrmtx;
    static std::map<uint32_t, uint32_t> lrs;
    uint32_t n = ++lrn;
    uint32_t lr = static_cast<uint32_t>(context->lr);
    {
      std::lock_guard<std::mutex> g(lrmtx);
      lrs[lr]++;
      if (n == 1 || n == 200000) {
        // Walk the guest back chain, as the crash reporter does: [sp] is the
        // caller's frame and its return address is [caller_sp - 8]. The LR
        // alone only names the innermost caller, and that one turned out to
        // be called from somewhere else in a loop.
        auto* um = kernel_state()->memory();
        uint32_t sp = static_cast<uint32_t>(context->r[1]);
        std::string bt;
        for (int f = 0; f < 10 && sp; ++f) {
          uint32_t caller_sp =
              xe::load_and_swap<uint32_t>(um->TranslateVirtual(sp));
          if (caller_sp <= sp || caller_sp - sp > 0x10000) break;
          uint32_t ra =
              xe::load_and_swap<uint32_t>(um->TranslateVirtual(caller_sp - 8));
          if (ra < 0x81000000u || ra >= 0x93000000u) break;
          bt += fmt::format("{:08X} ", ra);
          sp = caller_sp;
        }
        XELOGI("SysCmdBufCaller #{}: unwind {}", n, bt);
      }
      if (n == 200000 || n == 600000) {
        for (auto& kv : lrs) {
          XELOGI("SysCmdBufCaller: lr {:08X} x{}", kv.first, kv.second);
        }
      }
    }
  }
  {
    // Is this mechanism used at all? The Guide's drawing is expected to reach
    // the GPU through the system command buffer, and this stub hands back two
    // magic constants instead of one.
    static std::atomic<uint32_t> n{0};
    uint32_t c = ++n;
    if (in_guide_draw_scope || in_xam_createdevice_scope || c <= 5 ||
        (c % 2000) == 0) {
      auto* th = XThread::GetCurrentThread();
      XELOGI("VdGetSystemCommandBuffer #{}{} from '{}' p0={:08X} p1={:08X}", c,
             in_guide_draw_scope      ? " [GUIDE DRAW]"
             : in_xam_createdevice_scope ? " [XAM CREATEDEVICE]"
                                         : "",
             th ? th->name() : std::string("<none>"), p0_ptr.guest_address(),
             p1_ptr.guest_address());
    }
  }
  p0_ptr.Zero(0x94);
  xe::store_and_swap<uint32_t>(p0_ptr, 0xBEEF0000);
  xe::store_and_swap<uint32_t>(p1_ptr, 0xBEEF0001);
  if (::cvars::guide_syscmdbuf_buffer_kb > 0) {
    static uint32_t buf = 0, buf_size = 0;
    if (!buf) {
      buf_size = static_cast<uint32_t>(::cvars::guide_syscmdbuf_buffer_kb) * 1024;
      buf = kernel_state()->memory()->SystemHeapAlloc(buf_size, 4096);
      if (buf) {
        std::memset(kernel_state()->memory()->TranslateVirtual(buf), 0,
                    buf_size);
        XELOGI("VdGetSystemCommandBuffer: handing guest buffer {:08X} size {}",
               buf, buf_size);
      }
    }
    if (buf) {
      auto* b = reinterpret_cast<uint8_t*>(p0_ptr.host_address());
      xe::store_and_swap<uint32_t>(b + 0x04, buf);
      xe::store_and_swap<uint32_t>(b + 0x08, buf_size);
      guide_syscmdbuf_ptr_ = buf;
      guide_syscmdbuf_size_ = buf_size;
      // Under the forced-wait livelock the guest asks for this buffer tens of
      // thousands of times a second. Sample rarely: has it ever written into
      // what we handed it? The earlier answer was no, but that was measured in
      // the stable configuration where the guest was not retrying at all.
      static std::atomic<uint32_t> acq{0};
      uint32_t an = ++acq;
      if (an == 1 || (an % 50000) == 0) {
        auto* w = reinterpret_cast<const uint32_t*>(
            kernel_state()->memory()->TranslateVirtual(buf));
        uint32_t nz = 0;
        for (uint32_t i = 0; i < buf_size / 4; ++i) {
          if (w[i]) ++nz;
        }
        XELOGI("SysCmdBufAcq #{}: guest has written {} non-zero words into "
               "the buffer we handed it",
               an, nz);
      }
    }
  }
  if (::cvars::guide_syscmdbuf_fields) {
    // 819FE138 reads p0+30 and p0+34 and compares them against 0x500 and
    // 0x5BE. They are the only fields of the 0x94-byte descriptor with an
    // observed reader.
    auto* base = reinterpret_cast<uint8_t*>(p0_ptr.host_address());
    xe::store_and_swap<uint32_t>(base + 0x30, 0x500);
    xe::store_and_swap<uint32_t>(base + 0x34, 0x5BE);
    static std::atomic<uint32_t> once{0};
    if (once++ == 0) {
      XELOGI("VdGetSystemCommandBuffer: filled p0+30=0x500 p0+34=0x5BE");
    }
  }
}
DECLARE_XBOXKRNL_EXPORT1(VdGetSystemCommandBuffer, kVideo, kStub);

// Phase 1097: VdQuerySystemCommandBuffer (xboxkrnl 0x1C8) was declared in
// xboxkrnl_table.inc with NO BODY - the eighth export of that shape this
// project has hit. It only became visible once xam's own task pool started
// running (guest_native_timers + letting the guest dispatch its own skin
// loader): xam's HUD-manager loop polls it, and every call took Xenia's
// undefined-extern path, which FORMATS AND WRITES A LOG LINE. A 120 s run
// produced a 354 MB log, 264,560 of those lines in a single 20 MB slice.
// That is not a cosmetic problem - the logging is what the run spends its
// time on.
//
// The return value is MEASURED from the user's own kernel, not chosen.
// Ordinal 0x1C8 is VA 8008FEF8 there, and its first act after taking the lock
// at 800D0DE0 is:
//     8008FF18  lwz r10, 0x1CC(r31)     ; r31 = 800D0C00
//     8008FF20  cmplwi cr6, r10, 0
//     8008FF24  bne -> the three-slot ring at 800D0DD8
//     8008FF28  li r30, 0               ; else the result is zero
//     8008FF90  ... mr r3, r30          ; and that is what it returns
// so on a machine where the system command buffer subsystem was never brought
// up - which is exactly this emulator - the console's own answer is 0. The
// guest agrees: its only call site is 819FED58, which passes 0 and returns
// the result unchanged.
//
// This is the same value the undefined-extern path already returned, so guest
// behaviour is unchanged; what changes is that the emulator stops writing a
// log line per poll.
// Phase 1098h: THE RETURN VALUE ABOVE WAS RIGHT ABOUT THE KERNEL AND WRONG
// ABOUT THE CONSOLE, AND IT IS WHY THE GUIDE DOES NOT RENDER.
//
// Reading the whole of 8008FEF8 rather than its first branch, the result is a
// BOOLEAN, not a pointer:
//     8008FF18  r10 = [800D0C00+0x1CC]    ; null only if the subsystem is down
//     8008FF30  r11 = ([800D0C00+0x1D8]+1) % 3        ; next of three slots
//     8008FF50  r9  = [800D0C00+4 + r11*4]            ; that slot
//     8008FF64  r9  = head - slot ; r11 = head - gpu_pos
//     8008FF6C  subfc/subfe/addic. -> r30 = 1 or 0    ; "has the GPU passed it"
//     8008FF9C  return r30
// i.e. "IS A SYSTEM COMMAND BUFFER SLOT FREE". The `which` argument only
// selects an extra out-struct (8008FE80) and is 0 on the one path that matters.
//
// The old comment reasoned that a machine whose command-buffer subsystem was
// never brought up answers 0, and that is true of the KERNEL IMAGE. But on a
// console the kernel brings that subsystem up itself at video init, long before
// xam runs, so the console's answer is 1. Returning 0 here is not "the same
// value the undefined-extern path returned" in any meaningful sense - it is an
// answer no running console ever gives.
//
// MEASURED consequence of returning 0, phase 1098h:
//     81793288  bl 819FED58          ; -> this export, with which = 0
//     8179328C  cmpwi r3, 0
//     81793290  beq  8179329C        ; 0 -> SKIP the next two instructions
//     81793298  bl 81792928          ; xam's HUD TICK: XuiAnimRun, and the
//                                    ; call to 81A00080 -> VdSetSystemCommandBuffer
// The skip is two instructions long, which is below the >=4 threshold Xenia's
// coverage reports as a span, so it was invisible for eight phases. With the
// tick skipped: XuiAnimRun and XUITimeline_Run never run (both measured
// DECLARED-not-run), so the Guide's blade timeline - started by
// XuiElementPlayTimeline in 8174E220 for the Closed->Half transition - never
// advances, never posts its completion message 0x0F, never clears
// [CHUDBkgndScene+0x14], and the HUD-manager loop 81794BC8 spins on E_PENDING
// forty million times a run.
//
// It is also self-deadlocking: the tick is what calls VdSetSystemCommandBuffer
// (81A00080, measured DECLARED-not-run), so with the query answering 0 the
// buffer is never registered, and nothing can ever make the query answer
// anything else.
//
// What is truthful for Xenia: there is no three-slot system command buffer ring
// here, and the command processor consumes what is submitted rather than
// leaving a slot outstanding, so a slot is always free. That is a statement
// about the HOST's own state, which is this function's job to report; it
// hardcodes nothing about the Guide, and every decision that follows is the
// guest's. Gated so the old behaviour is one flag away.
dword_result_t VdQuerySystemCommandBuffer_entry(dword_t which) {
  if (!cvars::guide_sys_cmdbuf_ready) return 0;
  // Phase 1098w: answer the question the console answers, which is not "yes"
  // but "has the host finished with the slot you want to reuse".
  //
  // The guest writes its streams into THREE physical buffers and asks here
  // before recycling one. Answering an unconditional 1 - what unblocked this
  // phase - tells it every slot is always free, so it recycles ~236 times a
  // frame while the host executes one, and any queue the host keeps fills with
  // pointers to buffers that have been overwritten dozens of times. That is
  // measured: draining such a queue faulted the PM4 parser (1098v).
  //
  // So gate on the host's own backlog. Outstanding = submits published but not
  // yet executed; while that reaches the ring's depth, the slot the guest wants
  // is still in use and the truthful answer is 0. The guest then waits, exactly
  // as it would on hardware, the backlog stays small, and every queued pointer
  // still describes the bytes that were in it.
  if (cvars::guide_syscmd_slot_contract) {
    auto* gs = kernel_state()->emulator()->graphics_system();
    auto* cp = gs ? gs->command_processor() : nullptr;
    if (cp) {
      uint32_t h = cp->guide_syscmd_head_.load(std::memory_order_acquire);
      uint32_t t = cp->guide_syscmd_tail_.load(std::memory_order_acquire);
      if ((h - t) >= uint32_t(cvars::guide_syscmd_slots)) return 0;
    }
  }
  return 1;
}
DECLARE_XBOXKRNL_EXPORT1(VdQuerySystemCommandBuffer, kVideo, kStub);

// Phase 593: ordinal 0x1D8 is in the export table but had no implementation,
// so xam's import of it resolved to nothing. It is the call by which the
// system command buffer is registered, and phase 592 showed the Guide's
// buffer is never handed to the command processor. Log it to establish
// whether xam calls it at all, and with what.
void VdSetSystemCommandBuffer_entry(dword_t r3, dword_t r4) {
  // Phase 1098o: this takes ONE argument - a pointer to a descriptor the guest
  // builds ON ITS STACK. Measured at the call site 81A001E0:
  //     81A001D0  bl 8180D9F0          ; memcpy 0x38 bytes into [sp+0xA8]
  //     81A001E0  addi r3, r1, 0x50    ; r3 = &[sp+0x50]
  //     81A001E4  bl 81D10A0C          ; VdSetSystemCommandBuffer
  // so the 7027FA20 logged before was a STACK address and r4 was leftover
  // register content, not a second argument. The descriptor is transient: it
  // has to be read here, at the call, not remembered as a pointer.
  //
  // Dump it rather than guess its layout - the whole point of this phase is
  // that the Guide now writes a real PM4 stream into the buffer this
  // descriptor names, and the host does not consume it (src/xenia/gpu/ has no
  // notion of a system command buffer and only the one VdInitializeRingBuffer
  // ring). Knowing the field offsets is the prerequisite for routing it.
  static std::atomic<uint32_t> once{0};
  uint32_t n = ++once;
  // Phase 1098o: the descriptor's base changes every call (1FC68000, 1FC28000,
  // 1FBE8000 ...), which is the signature of a per-frame SUBMIT rather than a
  // one-time registration. Sample late as well as early so the call RATE is
  // measurable - that is what decides whether this export is the routing point.
  if (n <= 3 || n == 100 || n == 1000 || (n % 5000) == 0) {
    auto* mem = kernel_state()->memory();
    auto* d = mem->TranslateVirtual(uint32_t(r3));
    std::string dump;
    if (d) {
      for (uint32_t i = 0; i < 0x90; i += 4) {
        dump += fmt::format("{:08X} ", xe::load_and_swap<uint32_t>(
                                           static_cast<uint8_t*>(d) + i));
      }
    }
    XELOGI("VdSetSystemCommandBuffer #{} desc@{:08X}: {}", n, uint32_t(r3),
           dump.empty() ? "<unmapped>" : dump);
  }
  // Phase 1098p: publish the submitted stream for the GPU thread.
  if (cvars::guide_route_sys_cmdbuf) {
    auto* mem = kernel_state()->memory();
    auto* d = mem->TranslateVirtual(uint32_t(r3));
    if (d) {
      const uint32_t phys =
          xe::load_and_swap<uint32_t>(static_cast<uint8_t*>(d) + 0x00);
      const uint32_t words =
          xe::load_and_swap<uint32_t>(static_cast<uint8_t*>(d) + 0x04);
      auto* gs = kernel_state()->emulator()->graphics_system();
      auto* cp = gs ? gs->command_processor() : nullptr;
      if (cp && phys && words) {
        const uint64_t pair = (uint64_t(phys) << 32) | uint64_t(words);
        cp->guide_syscmd_pair_.store(pair, std::memory_order_release);
        // Phase 1098s: queue EVERY submit. Keeping only the latest dropped
        // ~235 of every 236 streams, and the resolve that moves the Guide's
        // pixels out of EDRAM was in the dropped ones.
        uint32_t h = cp->guide_syscmd_head_.load(std::memory_order_relaxed);
        uint32_t t = cp->guide_syscmd_tail_.load(std::memory_order_acquire);
        if (h - t < xe::gpu::CommandProcessor::kGuideSysCmdQueue) {
          cp->guide_syscmd_ring_[h % xe::gpu::CommandProcessor::kGuideSysCmdQueue].store(
              pair, std::memory_order_release);
          cp->guide_syscmd_head_.store(h + 1, std::memory_order_release);
        } else {
          cp->guide_syscmd_dropped_.fetch_add(1, std::memory_order_relaxed);
        }
        // Phase 1098zi: the descriptor's own logical surface size (+0x14 /
        // +0x18), which is 852x480 where the resolve pitch is 864.
        cp->guide_desc_width_ =
            xe::load_and_swap<uint32_t>(static_cast<uint8_t*>(d) + 0x14);
        cp->guide_desc_height_ =
            xe::load_and_swap<uint32_t>(static_cast<uint8_t*>(d) + 0x18);
        // Phase 1099a: WHERE DOES THE GUEST STATE THE GUIDE'S OPACITY?
        // The resolved surface is opaque (alpha 255 everywhere), so if there
        // is a background/plane alpha it is stated somewhere else. The submit
        // descriptor is 0x94 bytes and only +0x00/+0x04/+0x14/+0x18/+0x60..
        // +0x6C have ever been decoded. Census EVERY dword: how many distinct
        // values each one takes, and what they are. A per-frame opacity varies
        // or sits in [0,1] as a float; a constant does neither. This only
        // reads the guest's own descriptor.
        if (::cvars::guide_desc_census) {
          static std::array<std::set<uint32_t>, 0x94 / 4> seen;
          static std::atomic<uint32_t> ndesc{0};
          auto* db = static_cast<uint8_t*>(d);
          for (uint32_t i = 0; i < 0x94 / 4; ++i) {
            auto& sv = seen[i];
            if (sv.size() < 8) {
              sv.insert(xe::load_and_swap<uint32_t>(db + i * 4));
            }
          }
          uint32_t n = ++ndesc;
          if (n == 1 || n == 4000) {
            std::string out;
            for (uint32_t i = 0; i < 0x94 / 4; ++i) {
              const uint32_t v0 = *seen[i].begin();
              float f;
              std::memcpy(&f, &v0, 4);
              // Flag anything that reads as a plausible normalised float or a
              // small integer that could be a 0-255 alpha.
              const char* tag = "";
              if (f > 0.0f && f <= 1.0f) {
                tag = " <FLOAT[0,1]";
              } else if (v0 > 0 && v0 <= 255) {
                tag = " <BYTE";
              }
              out += fmt::format("\n  +{:02X} n={} v={:08X}{}", i * 4,
                                 seen[i].size(), v0, tag);
            }
            XELOGI("GuideDescCensus after {} submits:{}", n, out);
          }
        }
        // Phase 1099b: DOES THE GUEST'S COMMAND BUFFER GROW? "The Guide never
        // resets the draw, it piles on itself forever" would show here as a
        // word count that climbs instead of returning to a steady size each
        // frame. Log min/max/current periodically - all three from the guest's
        // own descriptor field +0x04.
        {
          static std::atomic<uint32_t> wmin{0xFFFFFFFFu}, wmax{0}, wn{0};
          uint32_t cur = words;
          uint32_t om = wmin.load();
          while (cur < om && !wmin.compare_exchange_weak(om, cur)) {}
          uint32_t oM = wmax.load();
          while (cur > oM && !wmax.compare_exchange_weak(oM, cur)) {}
          uint32_t k = ++wn;
          if ((k % 2000) == 0) {
            XELOGI("GuideCmdWords: submit {} cur={} min={} max={}", k, cur,
                   wmin.load(), wmax.load());
          }
        }
        cp->guide_syscmd_submits_.fetch_add(1, std::memory_order_relaxed);
        // Phase 1098u: does ANY submitted stream put the GPU in copy mode? A
        // resolve in Xenia is a draw issued while RB_MODECONTROL (0x2208) says
        // edram_mode == kCopy. The one stream dumped in 1098t does not write
        // that register, and the destination census never saw the Guide's
        // surface. Sample streams and count the ones that do, so "the guest
        // never asks for a resolve" is measured rather than inferred from a
        // single sample.
        static std::atomic<uint32_t> scan_n{0};
        static std::atomic<uint32_t> with_copy{0};
        static std::atomic<uint32_t> scanned{0};
        if ((scan_n.fetch_add(1, std::memory_order_relaxed) % 37) == 0) {
          const uint8_t* sp = mem->TranslatePhysical(phys);
          bool found = false;
          uint32_t found_val = 0;
          if (sp && words < 0x20000) {
            uint32_t i = 0;
            while (i < words) {
              uint32_t hdr = xe::load_and_swap<uint32_t>(sp + i * 4);
              uint32_t ty = hdr >> 30;
              if (ty == 0) {
                uint32_t cnt = ((hdr >> 16) & 0x3FFF) + 1;
                uint32_t base = hdr & 0x7FFF;
                bool one = (hdr & 0x8000) != 0;
                for (uint32_t k = 0; k < cnt && i + 1 + k < words; ++k) {
                  if ((one ? base : base + k) == 0x2208) {
                    found = true;
                    found_val =
                        xe::load_and_swap<uint32_t>(sp + (i + 1 + k) * 4);
                  }
                }
                i += 1 + cnt;
              } else if (ty == 1) {
                i += 3;
              } else if (ty == 2) {
                i += 1;
              } else {
                i += 1 + (((hdr >> 16) & 0x3FFF) + 1);
              }
            }
          }
          uint32_t sc = scanned.fetch_add(1, std::memory_order_relaxed) + 1;
          if (found) with_copy.fetch_add(1, std::memory_order_relaxed);
          if ((sc % 200) == 0) {
            XELOGI("GuideModeControl: {} of {} sampled streams write 0x2208 "
                   "(last value {:08X})",
                   with_copy.load(std::memory_order_relaxed), sc, found_val);
          }
        }
      }
    }
  }
}
DECLARE_XBOXKRNL_EXPORT1(VdSetSystemCommandBuffer, kVideo, kStub);

void VdSetSystemCommandBufferGpuIdentifierAddress_entry(lpunknown_t unk) {
  // r3 = 0x2B10(d3d?) + 8
}
DECLARE_XBOXKRNL_EXPORT1(VdSetSystemCommandBufferGpuIdentifierAddress, kVideo,
                         kStub);

// VdVerifyMEInitCommand
// r3
// r4 = 19
// no op?

dword_result_t VdInitializeScalerCommandBuffer_entry(
    dword_t scaler_source_xy,      // ((uint16_t)y << 16) | (uint16_t)x
    dword_t scaler_source_wh,      // ((uint16_t)h << 16) | (uint16_t)w
    dword_t scaled_output_xy,      // ((uint16_t)y << 16) | (uint16_t)x
    dword_t scaled_output_wh,      // ((uint16_t)h << 16) | (uint16_t)w
    dword_t front_buffer_wh,       // ((uint16_t)h << 16) | (uint16_t)w
    dword_t vertical_filter_type,  // 7?
    pointer_t<X_D3DFILTER_PARAMETERS> vertical_filter_params,    //
    dword_t horizontal_filter_type,                              // 7?
    pointer_t<X_D3DFILTER_PARAMETERS> horizontal_filter_params,  //
    lpvoid_t unk9,                                               //
    lpvoid_t dest_ptr,  // Points to the first 80000000h where the memcpy
                        // sources from.
    dword_t dest_count  // Count in words.
) {
  // Phase 1098z9: THIS MAY BE THE MISSING COMPOSITE. On the console this returns
  // a real PM4 command buffer that SCALES A SOURCE RECT ONTO AN OUTPUT RECT -
  // which is how the system overlay reaches the display - and the caller submits
  // it. Xenia fills it with NOPs, so whatever xam asks to be composited is
  // replaced by nothing. Every parameter is the GUEST's, so acting on them
  // invents no placement.
  //
  // Log the call before deciding anything: does xam call it at all, and with
  // what rectangles?
  {
    static std::atomic<uint32_t> sc_n{0};
    uint32_t n = ++sc_n;
    if (n <= 8 || (n % 500) == 0) {
      XELOGI("VdInitializeScalerCommandBuffer #{}: src xy={:08X} wh={:08X} | "
             "out xy={:08X} wh={:08X} | fb wh={:08X} | vfilt={} hfilt={} | "
             "dest={:08X} words={}",
             n, uint32_t(scaler_source_xy), uint32_t(scaler_source_wh),
             uint32_t(scaled_output_xy), uint32_t(scaled_output_wh),
             uint32_t(front_buffer_wh), uint32_t(vertical_filter_type),
             uint32_t(horizontal_filter_type), dest_ptr.guest_address(),
             uint32_t(dest_count));
    }
  }
  // We could fake the commands here, but I'm not sure the game checks for
  // anything but success (non-zero ret).
  // For now, we just fill it with NOPs.
  auto dest = dest_ptr.as_array<uint32_t>();
  for (size_t i = 0; i < dest_count; ++i) {
    dest[i] = 0x80000000;
  }

  uint32_t fb_x = (scaled_output_wh >> 16) & 0xFFFF;
  uint32_t fb_y = scaled_output_wh & 0xFFFF;
  const bool forced_widescreen =
      kernel_state()->xconfig()->ReadSetting<uint32_t>(
          XCONFIG_USER_CATEGORY, XCONFIG_USER_VIDEO_FLAGS) &
      X_VIDEO_FLAGS::Widescreen;

  auto aspect = CalculateScaledAspectRatio(fb_x, fb_y, forced_widescreen);

  auto graphics_system = kernel_state()->emulator()->graphics_system();
  graphics_system->SetScaledAspectRatio(aspect.first, aspect.second);

  return (uint32_t)dest_count;
}
DECLARE_XBOXKRNL_EXPORT2(VdInitializeScalerCommandBuffer, kVideo, kImplemented,
                         kSketchy);

struct BufferScaling {
  xe::be<uint16_t> fb_width;
  xe::be<uint16_t> fb_height;
  xe::be<uint16_t> bb_width;
  xe::be<uint16_t> bb_height;
};
void AppendParam(StringBuffer* string_buffer, pointer_t<BufferScaling> param) {
  string_buffer->AppendFormat(
      "{:08X}(scale {}x{} -> {}x{}))", param.guest_address(),
      uint16_t(param->bb_width), uint16_t(param->bb_height),
      uint16_t(param->fb_width), uint16_t(param->fb_height));
}

// Graphics notification routines. This is how the Guide reaches the screen:
// xam registers a renderer, the title calls the routines during its own
// frame, and xam's callback draws over the title's back buffer, which the
// title then swaps. Xenia previously had no registration function at all and
// a no-op for the call, so the title invoked the hook every frame and nothing
// happened. See research/FINDINGS.md phase 72.
struct GraphicsNotificationRoutine {
  uint32_t callback;
  uint32_t context;
  bool is_xam;
};
static xe::global_critical_region graphics_notification_region_;
static std::vector<GraphicsNotificationRoutine>* graphics_notification_routines_
    = nullptr;

uint32_t guide_prev_device_ = 0;
static uint32_t guide_draw_fn_ = 0;
// The device's own reservation window, sampled either side of the composite
// draw. 81A042E0 allocates packet space from [dev+0x30] and advances it; that
// is where the draw emitter 819F5D18 writes, and it is NOT the 81A01358 block
// that guide_bind_cmdbuf_kb repoints. Bracketing the cursor gives exactly the
// words one draw emitted, with no diffing and no guessing where the stream
// starts.
// Ordered checkpoints through the pre-draw path. With the ownership claim
// the run wedges before the composite draw is even reached, and the last
// line logged was a device survey - which narrows it to a stretch of code
// with several guest calls in it. Naming each block as it is entered says
// which one, instead of another round of disassembly and inference.
static bool ckpt_on = false;
static uint32_t guide_claim_dev_ = 0;
static uint32_t guide_claim_prev_ = 0;
static std::atomic<void*> guide_stall_thread_{nullptr};
// Recovered 2026-08-29: accessors lost when the refactor incident destroyed
// this file; the storage above survived the replay but these did not.
void* GuideStallThread() { return guide_stall_thread_.load(); }
void GuidePublishStallThread(void* h) { guide_stall_thread_ = h; }
static uint32_t guide_first_visual_node_ = 0;
static uint32_t guide_resv_dev_ = 0;
static uint32_t g_draw_entry_reserve = 0;
static uint32_t g_draw_entry_cmdbase = 0;

// Resolve the guest thread xam recorded as its XUI render thread.
//
// 81778BB8 is six instructions: r10 = [r13+256] (current thread), r11 =
// [0x81D42520] (recorded render thread), return r10 == r11. It is called at
// the entry of 46 functions across the render subsystem and every call site
// traps when it returns 0 - including 81792928, the only route to 819FF7A0,
// which is what sets [dev+16344] and clears the 0x20 latch that makes the
// vertex allocator refuse.
//
// Measured: the slot holds 3002A010 and the bootstrap runs on 30052010, so
// the gate has always failed. Executing against the recorded thread's
// ThreadState makes r13 - and therefore the comparison - come out right,
// which satisfies the gate the way xam means it instead of writing the slot.
static xe::cpu::ThreadState* GuideRenderThreadState() {
  auto* ks = kernel_state();
  if (!ks || !ks->memory()) {
    return nullptr;
  }
  if (!XamAddrInImage(XamUiThreadSlot(), 4)) {
    return nullptr;  // dashroot-only slot; not present on this build
  }
  uint32_t want =
      xe::load_and_swap<uint32_t>(ks->memory()->TranslateVirtual(XamUiThreadSlot()));
  if (!want) {
    return nullptr;
  }
  static bool logged = false;
  for (uint32_t id : ks->GetAllThreadIDs()) {
    auto th = ks->GetThreadByID(id);
    if (th && th->guest_object() == want) {
      if (!logged) {
        logged = true;
        // Name it once. Which xam thread this turns out to be decides the
        // next move: if it is a thread whose proc is 81794BC8 then that loop
        // is what should have called 819FF7A0 on its own, and the question
        // becomes why it is not running rather than which state to borrow.
        XELOGI("GuideRenderThread: guest={:08X} id={} name='{}'", want, id,
               th->thread_name());
      }
      return th->thread_state();
    }
  }
  if (!logged) {
    logged = true;
    XELOGW("GuideRenderThread: [81D42520]={:08X} matches no live XThread", want);
  }
  return nullptr;
}
static uint32_t guide_resv_pre_ = 0;
static uint32_t guide_cmdbuf_base_ = 0;
static uint32_t guide_boot_dc_ = 0;
static uint32_t guide_cmdbuf_size_ = 0;
static uint32_t guide_draw_this_ = 0;

static uint32_t g_xam_lo = 0;
static uint32_t g_xam_hi = 0;
uint32_t XamUiThreadSlot();
uint32_t XamDeviceSlot();
// hud's XUI-init and render entry points, located by signature in the
// emulator and published here. dashroot +0xA898/+0xAB28, retail +0x98F8/
// +0x9B88; the draw-hook install below used the dashroot offsets, which is
// why retail installed no hook and drew nothing.
static uint32_t g_hud_xuiinit = 0;
static uint32_t g_hud_render = 0;
void SetHudEntries(uint32_t xuiinit, uint32_t render) {
  g_hud_xuiinit = xuiinit;
  g_hud_render = render;
  XELOGI("SetHudEntries: xuiinit {:08X} render {:08X}", xuiinit, render);
}
void SetXamImageExtent(uint32_t lo, uint32_t hi) {
  g_xam_lo = lo;
  g_xam_hi = hi;
  // Resolve eagerly. Lazily, these only fire on paths a given build happens to
  // reach - retail never called XamDeviceSlot at all, so it went unvalidated
  // while looking fine. Resolving here means every run reports both, on both
  // builds, whether or not anything later uses them.
  XamUiThreadSlot();
  XamDeviceSlot();
  XamRenderHost();
  XamXuiCtxSlot();
  XamProviderSlot();
}
bool XamAddrInImage(uint32_t addr, uint32_t len) {
  return g_xam_lo && addr >= g_xam_lo && addr + len <= g_xam_hi;
}

// The slot holding xam's recorded UI thread. dashroot puts it at 81D42520;
// retail 17559 at 81AA09F0. Both are read by the same six-instruction identity
// check - lwz rX,256(r13) (current thread), load the slot, subtract, cntlzw,
// rlwinm ..,27,31,31 - so find that shape and decode the address out of its
// lis/addi/lwz triple rather than hardcoding either value.
static uint32_t g_ui_thread_slot = 0;
static bool g_ui_thread_slot_done = false;
// xam's device global. dashroot puts it at 81D43684, retail 17559 at
// 81AA1B14. Both are the out-parameter of the same device-creation function,
// whose head is the XboxHardwareInfo bit-0x200 gate; the slot address is built
// by a lis/addi pair 0x58 bytes in. Find the function by masked signature and
// decode the pair, rather than hardcoding either address.
static uint32_t g_xam_dev_slot = 0;
static bool g_xam_dev_slot_done = false;
// xam's XUI render host. dashroot 8178DC58, retail 17559 816C8328. The two
// are the same function except retail has no thread-identity assertion, which
// is why a whole-prologue signature and a role match both failed (phases
// 429-430). Anchor on what they share: the standard prologue with a 240-byte
// frame, then within a few instructions memset(r1+100, 0, 120).
static uint32_t g_render_host = 0;
static bool g_render_host_done = false;
// The XUI context pointer slot. dashroot 81D6C978, retail 17559 81AC7DE4.
// No shape-based scan finds it: its dashroot accessor has no counterpart in
// retail, and dashroot's copy carries CALLCAP marker nops that shift every
// offset (phase 433). Positional anchor instead - in BOTH builds the render
// host calls a ctx-reading helper immediately before it calls XuiInit, and
// that helper's first global load is the slot.
static uint32_t g_xui_ctx_slot = 0;
static uint32_t g_xui_createdc = 0;  // the helper itself, not just its slot
static bool g_xui_ctx_slot_done = false;
uint32_t XamXuiCreateDC() { return g_xui_createdc; }
// The XUI resource-provider slot. dashroot 81D6D0AC, retail 17559 81AC82FC.
// Both are the SECOND global store performed by XuiInit (export ordinal
// 0x340), and in both builds the second and third stores are 0xC apart - a
// structural corroboration that the ordering is the same object, not a
// coincidence of position.
static uint32_t g_provider_slot = 0;
static bool g_provider_slot_done = false;
// Is the loaded xam the dashroot build these hardcoded tables came from?
// Some blocks are lists of dozens of build-specific function addresses (the
// 39 XUI class registrars, the device-creation entries) where converting each
// by signature is not practical. Those addresses all fall inside retail's
// image too, so a range check cannot reject them - the resolved structures
// can. If the device and UI-thread slots are dashroot's, the tables apply.
bool XamIsDashrootLayout() {
  return XamDeviceSlot() == 0x81D43684u && XamUiThreadSlot() == 0x81D42520u;
}

// Phase 440 left 22 hardcoded dashroot addresses that this research code calls
// outright. Four have now been caught one crash at a time (817503E8,
// 81A01358, XuiObjectFromHandle, 818FB2B8). Rewriting the 39 call sites is
// what destroyed this file, so instead each constant is wrapped in place:
// GuideConst(0x818FB038u) is a token swap, which cannot reorder anything.
//
// On a non-dashroot build it returns the address of a `blr` inside the loaded
// xam image - a real, executable, already-mapped instruction that returns
// immediately - so the call is harmless instead of jumping into an unrelated
// function. Returning 0 would just move the fault to address 0.
static uint32_t g_nop_fn = 0;
uint32_t GuideNopFn() {
  if (g_nop_fn) return g_nop_fn;
  if (!kernel_state() || !g_xam_lo) return 0;
  uint32_t lo = g_xam_lo, hi = g_xam_hi;
  auto* mem = kernel_state()->memory();
  for (uint32_t a = lo; a && a + 4 <= hi; a += 4) {
    if (xe::load_and_swap<uint32_t>(mem->TranslateVirtual(a)) == 0x4E800020u) {
      g_nop_fn = a;
      XELOGI("GuideConst: using blr at {:08X} as the no-op for this build", a);
      break;
    }
  }
  return g_nop_fn;
}

// Phase 519: [81D6C9C8] holds the stand-in at bootstrap entry and reads zero by
// XuiRenderCreateDC, so one of the early bootstrap calls clears it wholesale -
// no store to it exists anywhere in the image. Installing once is therefore not
// enough; re-establish it wherever it is found null.
static void GuideEnsureStandin(const char* tag) {
  if (!::cvars::guide_patch_skin_dispatch) return;
  auto* m = kernel_state()->memory();
  uint32_t cur = xe::load_and_swap<uint32_t>(m->TranslateVirtual(0x81D6C9C8u));
  if (cur) {
    XELOGI("Standin @{}: already {:08X}", tag, cur);
    return;
  }
  // Phase 603: 819106F8 compares [81D6C9C8] against the static object
  // 81D6CA00 and routes to a failing vtable[0] call when they differ. A
  // fabricated block always differs, so the stand-in itself is what selects
  // the failing path. Offer the real object instead.
  if (::cvars::guide_skin_dispatch_real) {
    xe::store_and_swap<uint32_t>(m->TranslateVirtual(0x81D6C9C8u),
                                 0x81D6CA00u);
    XELOGI("Standin @{}: installed real object 81D6CA00", tag);
    return;
  }
  uint32_t blk = m->SystemHeapAlloc(0x80, 16);
  uint32_t nopfn = GuideNopFn();
  if (!blk || !nopfn) {
    XELOGW("Standin @{}: cannot build (blk={:08X} nop={:08X})", tag, blk, nopfn);
    return;
  }
  std::memset(m->TranslateVirtual(blk), 0, 0x80);
  uint32_t vt = blk + 0x40u;
  xe::store_and_swap<uint32_t>(m->TranslateVirtual(blk), vt);
  for (uint32_t sl = 0; sl < 16; ++sl) {
    xe::store_and_swap<uint32_t>(m->TranslateVirtual(vt + sl * 4u), nopfn);
  }
  xe::store_and_swap<uint32_t>(m->TranslateVirtual(0x81D6C9C8u), blk);
  XELOGI("Standin @{}: installed {:08X}", tag, blk);
}

uint32_t GuideConst(uint32_t addr) {
  if (XamIsDashrootLayout()) return addr;
  static uint32_t reported[64] = {};
  static size_t reported_n = 0;
  bool seen = false;
  for (size_t i = 0; i < reported_n; ++i) {
    if (reported[i] == addr) { seen = true; break; }
  }
  if (!seen) {
    if (reported_n < xe::countof(reported)) reported[reported_n++] = addr;
    XELOGW("GuideConst: {:08X} is a dashroot address - substituting a no-op",
           addr);
  }
  uint32_t nop = GuideNopFn();
  return nop ? nop : addr;
}

// Phase 509: a fixed 1280x720 surface needs 0x2AA blocks and the pool typically
// has fewer free, so 819E7528 fails its fit check at 819E75EC and the Guide ends
// up with no render target at all (phase 508). Fall back through smaller sizes
// and take the first that fits - 852x480 matches the measured element bounds and
// is what this picks in practice.
//
// This is a workaround, not the fix: a smaller target means the Guide renders at
// the wrong resolution. It exists so the open question from phase 506 - whether
// the missing render target is what stops the elements emitting - can be tested.
// Phase 517: patch one guest instruction, with the protect/verify/log dance the
// RT-unbind patch needed. The xam text pages are mapped read-only and the guest
// heap's Protect() does not lift that, so this goes at the host page directly;
// a bare store faults at the host mapping and kills the run before logging,
// which reads exactly like "the patch code never executed".
// Phase 567: resolve a XUI handle to its object through the generation-checked
// table at 81D6D0D8. Phases 558-566 traced every remaining failure to this
// harness installing handles where hud and xam expect object pointers; the fix
// has to be applied at every install, not one, which is why phase 559's
// single-site change moved the fault instead of clearing it.
uint32_t GuideResolveHandle(uint32_t handle) {
  if (!handle) return 0;
  auto* m = kernel_state()->memory();
  auto r = [m](uint32_t a) {
    return xe::load_and_swap<uint32_t>(m->TranslateVirtual(a));
  };
  uint32_t idx = handle & 0xFFFFu, tag = handle >> 16;
  uint32_t bucket = r(0x81D6D0D8u + (idx >> 8) * 4u);
  if (!bucket) return 0;
  uint32_t entry = bucket + (idx & 0xFFu) * 8u;
  return (r(entry) == tag) ? r(entry + 4u) : 0;
}

// Phase 680: 8194A0A8 consults three slots per chain node - a global hook, a
// handle in [+4] resolved through the same table, and [+0x1C]/[+0x20]. Coverage
// says the first two never fire (phase 678), but that is inference from an
// unexecuted span. The table at 81D6D0D8 is host-readable, so walk it and read
// the slots directly. Phase 679 spent a scan on a struct that merely shared the
// offsets; observation settles what pattern-matching could not.
void GuideDumpNodes() {
  // Phase 787: this used to be a one-shot on the first draw, and its per-node
  // print is capped at 20 lines, so what it produced was a 20-of-58 SAMPLE of
  // the tree at its earliest moment - which phase 786 then compared against
  // phase 759's 1286-node figure as though the two were commensurable. Take
  // three snapshots instead, and count every node by class rather than
  // printing a prefix, so growth and composition are both visible.
  static uint32_t passes = 0;
  ++passes;
  // Phase 788: passes 1/5/10 are the first ten composite draws, which all
  // happen within a few thousand log lines of each other - far too narrow to
  // tell a settled tree from one still loading. Keep sampling for the whole
  // run so a late-arriving scene is visible.
  if (passes != 1 && passes != 5 && passes != 10 && (passes % 100) != 0) {
    return;
  }
  auto* m = kernel_state()->memory();
  // The first cut of this walked the table dereferencing whatever it found and
  // took 4 host faults, killing the composite draw - phase 672's mistake in a
  // new costume. Guard every read, and count what the guard rejects so a short
  // table is visibly a short table and not a silent zero.
  auto readable = [m](uint32_t a) {
    auto* hp = m->LookupHeap(a);
    return hp && hp->QueryRangeAccess(a, a + 0x24u) !=
                     xe::memory::PageAccess::kNoAccess;
  };
  auto r = [m](uint32_t a) {
    return xe::load_and_swap<uint32_t>(m->TranslateVirtual(a));
  };
  uint32_t cap = r(0x81D6D0D8u + 0x420u);
  XELOGI("GuideNodes: capacity={} global_hook={:08X}", cap, r(0x81D6D028u));
  uint32_t total = 0, with_base = 0, with_fn = 0, shown = 0, skipped = 0;
  std::map<uint32_t, uint32_t> by_class;
  uint32_t last_node = 0;
  for (uint32_t idx = 0; idx < cap && idx < 0x10000u; ++idx) {
    uint32_t bucket = r(0x81D6D0D8u + (idx >> 8) * 4u);
    uint32_t entry = bucket + (idx & 0xFFu) * 8u;
    if (!bucket || !readable(entry)) {
      ++skipped;
      continue;
    }
    uint32_t rec = r(entry + 4u);
    if (!rec || !readable(rec)) {
      ++skipped;
      continue;
    }
    uint32_t node = r(rec + 0x0Cu);
    if (!node || !readable(node)) {
      ++skipped;
      continue;
    }
    ++total;
    uint32_t base = r(node + 4u), fn = r(node + 0x1Cu);
    ++by_class[fn];
    if (base) ++with_base;
    if (fn) ++with_fn;
    if (node != last_node && shown < 20) {
      last_node = node;
      ++shown;
      XELOGI(
          "GuideNode[{}] node={:08X} self={:08X} base={:08X} next={:08X} "
          "fn={:08X} ctx={:08X}",
          idx, node, r(node), base, r(node + 8u), fn, r(node + 0x20u));
    }
  }
  XELOGI("GuideNodes[pass {}]: total={} with_base={} with_fn={} skipped={}",
         passes, total, with_base, with_fn, skipped);
  // Full histogram over every counted node - the point of the walk. Handler
  // address maps to a class via the registration table (phase 772).
  std::string hist;
  for (auto& kv : by_class) {
    hist += fmt::format("{:08X}x{} ", kv.first, kv.second);
  }
  XELOGI("GuideNodeClasses[pass {}]: {}", passes, hist);
  // Phase 759: which classes are actually in the tree? The handler at [+0x1C]
  // varies by class, and the harness's CreateByName probe made a XuiShader
  // instance with handle 00010504 - so resolving that names the XuiShader
  // handler, and tallying handlers counts how many elements use it.
  {
    std::map<uint32_t, uint32_t> by_fn;
    for (uint32_t idx = 0; idx < cap && idx < 0x10000u; ++idx) {
      uint32_t bucket = r(0x81D6D0D8u + (idx >> 8) * 4u);
      uint32_t entry = bucket + (idx & 0xFFu) * 8u;
      if (!bucket || !readable(entry)) continue;
      uint32_t rec = r(entry + 4u);
      if (!rec || !readable(rec)) continue;
      uint32_t node = r(rec + 0x0Cu);
      if (!node || !readable(node)) continue;
      ++by_fn[r(node + 0x1Cu)];
    }
    uint32_t shader_fn = 0;
    uint32_t sh = GuideResolveHandle(0x00010504u);
    if (sh && readable(sh)) {
      uint32_t shnode = r(sh + 0x0Cu);
      if (shnode && readable(shnode)) shader_fn = r(shnode + 0x1Cu);
    }
    std::string list;
    for (auto& kv : by_fn) {
      list += fmt::format("{:08X}x{}{} ", kv.first, kv.second,
                          (shader_fn && kv.first == shader_fn) ? "<-SHADER" : "");
    }
    XELOGI("GuideNodeClasses: {} distinct handlers | XuiShader fn={:08X} | {}",
           by_fn.size(), shader_fn, list);
  }
}


// Phase 694: 81A02940 allocates GPU-visible DATA memory and refuses while
// [dev+0x2B3D] & 0x20 is set (682). Phase 683 forced the guard and hit the
// assert in 81A02688 - that disabled the check reporting the problem. This
// supplies the missing service instead: a bump allocator over physical memory
// the harness owns, so 819E01E0 has a real address to convert and 819DCCA0
// can proceed past 819DCD18 with a legitimate buffer.
static uint32_t guide_alloc_arena_ = 0;
static uint32_t guide_alloc_end_ = 0;

void GuideInstallAllocStub() {
  auto* mem = kernel_state()->memory();
  auto* heap = mem->LookupHeapByType(true, 64 * 1024);
  if (!heap) {
    XELOGW("GuideAllocStub: no physical heap");
    return;
  }
  // Phase 695: 1MB, not 8. The allocator is called 38 times a run and the
  // arena is never reused, so 8MB was arbitrary - and it comes out of the same
  // physical heap the title allocates from, which is a candidate for the new
  // crash in the title's code.
  // Phase 844: this was 8MB when the stub first produced DRAW_INDX=16 (694);
  // it is 1MB now, and today's run with the stub emits 2789 words of float
  // payload against that run's 6917 words of command data. A bump allocator
  // that runs out returns nothing, and geometry is what stops being produced,
  // so restore the size the working measurement used.
  const uint32_t kSize = 32u * 1024u * 1024u;  // phase 1054: sizes are 4x what the stub assumed; keep ~100 paints of vertex data
  uint32_t buf = 0;
  if (!heap->Alloc(kSize, 4096,
                   kMemoryAllocationReserve | kMemoryAllocationCommit,
                   kMemoryProtectRead | kMemoryProtectWrite, false, &buf) ||
      !buf) {
    XELOGW("GuideAllocStub: physical allocation failed");
    return;
  }
  // Phase 695: zero the whole arena once. The stub never reuses memory, so a
  // single memset makes every allocation zeroed - which is what a real pool
  // hands out, and the cheapest explanation for phase 694's new guest crash in
  // the title's range: xam's other 34 callers of this allocator were getting
  // raw memory.
  std::memset(mem->TranslateVirtual(buf), 0, kSize);
  // [buf] holds the cursor; allocations start past it, 256-aligned.
  xe::store_and_swap<uint32_t>(mem->TranslateVirtual(buf), buf + 256u);
  const uint32_t lo = buf & 0xFFFFu;
  const uint32_t hi = (buf >> 16) + ((buf & 0x8000u) ? 1u : 0u);
  // r3 = dev, r4 = size, r5 = align; return the block in r3.
  //
  // Phase 696: the allowed return address lives at [buf+4], so which caller is
  // served is a runtime choice. guide_alloc_lr = 0 serves everyone (phase
  // 694's behaviour: DRAW_INDX=16 plus a guest crash); a specific value serves
  // only that call site. LR is still the caller's return address here - this
  // is the function entry, before any prologue.
  // Phase 697: serve callers whose return address falls in [lo, hi]. The
  // bounds live at [buf+4] and [buf+8]; [buf+12] is the arena end. lo == 0
  // serves every caller (phase 694's behaviour).
  const uint32_t allow_lo = uint32_t(::cvars::guide_alloc_lr);
  const uint32_t allow_hi = ::cvars::guide_alloc_lr_hi
                                ? uint32_t(::cvars::guide_alloc_lr_hi)
                                : allow_lo;
  xe::store_and_swap<uint32_t>(mem->TranslateVirtual(buf + 4u), allow_lo);
  xe::store_and_swap<uint32_t>(mem->TranslateVirtual(buf + 8u), allow_hi);
  xe::store_and_swap<uint32_t>(mem->TranslateVirtual(buf + 12u), buf + kSize);
  // Phase 1054: [buf+16] is where the cursor wraps to. The settled Guide
  // allocates ~72 KB a paint through this allocator (vertex and constant
  // payload), so a bump allocator empties 8 MB in four seconds; a ring keeps
  // the last few paints' payload intact, which is all a replayed stream needs.
  xe::store_and_swap<uint32_t>(mem->TranslateVirtual(buf + 16u), buf + 256u);
  guide_alloc_arena_ = buf;
  guide_alloc_end_ = buf + kSize;
  // Phase 908: 819E01E0 converts a pointer to a GPU address and returns zero
  // for anything outside the physical window at 0xA0000000 (545). The emitter
  // hands it this arena directly (907), so whether these addresses are inside
  // that window decides whether the conversion can succeed at all.
  XELOGI("GuideAllocStub: arena {:08X}..{:08X} | in 0xA0000000 window: {}", buf,
         buf + kSize, (buf >= 0xA0000000u && buf < 0xC0000000u) ? "yes" : "NO");
  // Branch displacements are computed after assembly rather than written by
  // hand - the prefix length varies with the gate, and one miscounted offset
  // would be a jump into the middle of the allocator.
  std::vector<uint32_t> code;
  std::vector<size_t> to_zero;
  if (allow_lo) {
    code.push_back(0x7C0802A6u);               // mflr   r0
    code.push_back(0x3D600000u | hi);          // lis    r11, hi
    code.push_back(0x812B0000u | (lo + 4u));   // lwz    r9, lo+4(r11)
    code.push_back(0x7C004840u);               // cmplw  r0, r9
    to_zero.push_back(code.size());
    code.push_back(0x41800000u);               // blt    -> return 0
    code.push_back(0x812B0000u | (lo + 8u));   // lwz    r9, lo+8(r11)
    code.push_back(0x7C004840u);               // cmplw  r0, r9
    to_zero.push_back(code.size());
    code.push_back(0x41810000u);               // bgt    -> return 0
  } else {
    code.push_back(0x3D600000u | hi);          // lis    r11, hi
  }
  // Phase 1054: the original (81A02940: mr r29,r4; slwi r29,r29,2; cmplw
  // r29,[dev+0x3FE0]) takes the size in DWORDS. Advancing by r4 bytes made
  // every block a quarter of its true size, so each draw's vertex data was
  // overwritten from byte 256 on by the next allocation - the fifth, ninth,
  // thirteenth glyph of every string vanished ("Xbox ome", "Sele t"), and
  // stray triangles (the hairline) came from the same overlap.
  code.push_back(0x5484103Au);                 // slwi   r4, r4, 2      dwords -> bytes
  code.push_back(0x814B0000u | lo);            // lwz    r10, lo(r11)  cursor
  code.push_back(0x394A00FFu);                 // addi   r10, r10, 255
  code.push_back(0x554A002Eu);                 // rlwinm r10, r10, 0, 0, 23
  code.push_back(0x7D2A2214u);                 // add    r9, r10, r4
  code.push_back(0x810B0000u | (lo + 12u));    // lwz    r8, lo+12(r11) end
  code.push_back(0x7C094040u);                 // cmplw  r9, r8
  // Phase 1054: on overflow wrap to [buf+16] (the ring) and retry once.
  code.push_back(0x40810014u);                 // ble    +0x14 -> store
  code.push_back(0x814B0000u | (lo + 16u));    // lwz    r10, lo+16(r11) wrap base
  code.push_back(0x7D2A2214u);                 // add    r9, r10, r4
  code.push_back(0x7C094040u);                 // cmplw  r9, r8
  to_zero.push_back(code.size());
  code.push_back(0x41810000u);                 // bgt    -> return 0 (block larger than the ring)
  code.push_back(0x912B0000u | lo);            // stw    r9, lo(r11)
  code.push_back(0x7D435378u);                 // mr     r3, r10
  code.push_back(0x4E800020u);                 // blr
  const size_t zero_idx = code.size();
  code.push_back(0x38600000u);                 // li     r3, 0
  code.push_back(0x4E800020u);                 // blr
  for (size_t bi : to_zero) {
    code[bi] |= uint32_t((zero_idx - bi) * 4u) & 0xFFFCu;
  }
  // xam's code pages are not writable; GuidePatchWord unprotects before each
  // store and restores after. Writing directly faulted the host at
  // fault_addr=181A02940 and took the run down with it.
  uint8_t* hp = mem->TranslateVirtual(0x81A02940u);
  void* page =
      reinterpret_cast<void*>(reinterpret_cast<uintptr_t>(hp) & ~0xFFFull);
  xe::memory::PageAccess old_access = xe::memory::PageAccess::kNoAccess;
  if (!xe::memory::Protect(page, 0x1000, xe::memory::PageAccess::kReadWrite,
                           &old_access)) {
    XELOGW("GuideAllocStub: cannot unprotect 81A02940");
    return;
  }
  for (size_t i = 0; i < code.size(); ++i) {
    xe::store_and_swap<uint32_t>(hp + i * 4u, code[i]);
  }
  xe::memory::Protect(page, 0x1000, old_access, nullptr);
  XELOGI("GuideAllocStub: buf={:08X} size={}KB cursor={:08X} allow_lr={:08X}; "
         "81A02940 replaced ({} instrs)",
         buf, kSize / 1024, buf + 256u, allow_lo, code.size());
}

bool GuidePatchWord(uint32_t addr, uint32_t expect, uint32_t value,
                    const char* name) {
  auto* pm = kernel_state()->memory();
  uint8_t* hp = pm->TranslateVirtual(addr);
  xe::memory::PageAccess old_access = xe::memory::PageAccess::kNoAccess;
  void* page = reinterpret_cast<void*>(
      reinterpret_cast<uintptr_t>(hp) & ~0xFFFull);
  if (!xe::memory::Protect(page, 0x1000, xe::memory::PageAccess::kReadWrite,
                           &old_access)) {
    XELOGW("{}: cannot unprotect {:08X}", name, addr);
    return false;
  }
  uint32_t was = xe::load_and_swap<uint32_t>(hp);
  bool ok = (was == expect);
  if (ok) {
    xe::store_and_swap<uint32_t>(hp, value);
    XELOGI("{}: {:08X} {:08X} -> {:08X} (readback {:08X})", name, addr, was,
           value, xe::load_and_swap<uint32_t>(hp));
  } else {
    XELOGW("{}: {:08X} reads {:08X}, expected {:08X} - not patching", name,
           addr, was, expect);
  }
  xe::memory::Protect(page, 0x1000, old_access, nullptr);
  return ok;
}

static uint32_t GuideMakeSurface(xe::cpu::Processor* proc,
                                 xe::cpu::ThreadState* ts) {
  static const uint32_t kSizes[][2] = {{1280, 720}, {852, 480}, {640, 480},
                                       {640, 640},  {512, 512}, {256, 256}};
  for (const auto& wh : kSizes) {
    uint64_t ca[] = {wh[0], wh[1], 0x18280186u, 0, 0};
    uint32_t s = static_cast<uint32_t>(
        proc->Execute(ts, GuideConst(0x819E7528u), ca, xe::countof(ca)));
    if (s) {
      XELOGI("GuideMakeSurface: {}x{} -> {:08X}", wh[0], wh[1], s);
      return s;
    }
    XELOGW("GuideMakeSurface: {}x{} did not fit", wh[0], wh[1]);
  }
  return 0;
}

// Phase 588: bind a render target on an arbitrary device. DrawSurfBind
// already does exactly this, but only for the device the draw hook happens to
// hold; the device hud's render is driven against is a different one, reached
// as [[bootDC+0x1CC]+0x0C], and nothing has ever bound a surface on it.
// `ts` is a xe::cpu::ThreadState* (kept as void* so this header does not have
// to pull in the cpu headers, matching GuidePublishStallThread).
static void EmitGuideCoverageOnce();  // defined below

// Phase 589: the readbacks all sit at the end of something - the paint loop,
// or 900 swaps in. A guest crash reaches neither, so coverage went silent in
// exactly the runs where the path mattered most. Callable from the crash
// handler.
void GuideEmitCoverageNow() { EmitGuideCoverageOnce(); }

uint32_t GuideBindDeviceRt(uint32_t dev, void* ts) {
  if (!dev || !ts) {
    return 0;
  }
  auto* mem = kernel_state()->memory();
  auto rdv = [&](uint32_t a) {
    return xe::load_and_swap<uint32_t>(mem->TranslateVirtual(a));
  };
  uint32_t existing = rdv(dev + 0x32B0u);
  if (existing) {
    return existing;
  }
  uint32_t surf = GuideMakeSurface(kernel_state()->processor(),
                                   static_cast<xe::cpu::ThreadState*>(ts));
  if (!surf) {
    XELOGW("GuideBindDeviceRt: surface creation returned 0 for dev {:08X}",
           dev);
    return 0;
  }
  for (uint32_t off : {0x32A0u, 0x32B0u, 0x3F70u, 0x3F74u, 0x3F78u}) {
    xe::store_and_swap<uint32_t>(mem->TranslateVirtual(dev + off), surf);
  }
  XELOGI("GuideBindDeviceRt: dev={:08X} surf={:08X} -> [32A0]={:08X} "
         "[32B0]={:08X} [3F78]={:08X}",
         dev, surf, rdv(dev + 0x32A0u), rdv(dev + 0x32B0u),
         rdv(dev + 0x3F78u));
  return surf;
}

// Phase 589: the same command-buffer setup the draw hook performs, but for an
// arbitrary device. 81A015B8 emits a packet word with `stw r10, 0(r11)` where
// r11 = [cursor]+4, so a zero cursor stores to address 4 - the 81A01638 fault.
// The hook's version (guide_bind_cmdbuf_kb) computes its device by this exact
// chain but keys off guide_draw_this_ and only runs from a draw that is not
// firing here, so this device never got a buffer.
uint32_t GuideBindDeviceCmdbuf(uint32_t dev, void* ts, uint32_t kb) {
  if (!dev || !ts || !kb) {
    return 0;
  }
  auto* mem = kernel_state()->memory();
  auto rdv = [&](uint32_t a) {
    return xe::load_and_swap<uint32_t>(mem->TranslateVirtual(a));
  };
  if (rdv(dev + 0x2B4Cu)) {
    // Phase 657: publish on this path too. Returning silently here meant
    // guide_cmdbuf_base_ stayed zero whenever a buffer was already bound,
    // which gates the second-context path shut for a reason that reads as
    // "the binder never ran" - it ran and took the early exit.
    uint32_t existing = rdv(dev + 0x2B48u);
    if (existing && !guide_cmdbuf_base_) {
      guide_cmdbuf_base_ = existing;
      guide_cmdbuf_size_ = kb * 1024u;
      XELOGI("GuideBindDeviceCmdbuf: already bound on {:08X}, publishing "
             "base {:08X}", dev, existing);
    }
    return existing;
  }
  uint32_t csize = kb * 1024u;
  static uint32_t cbuf = 0;
  if (!cbuf) {
    // Phase 592: this used the default (virtual) heap and got 0x3008F000,
    // while every buffer xam uses itself sits at 0x40xxxxxx. A command
    // buffer has to be memory the GPU can fetch from, so allocate physical.
    cbuf = mem->SystemHeapAlloc(csize, 4096, kSystemHeapPhysical);
    if (cbuf) {
      std::memset(mem->TranslateVirtual(cbuf), 0, csize);
    }
  }
  if (!cbuf) {
    XELOGW("GuideBindDeviceCmdbuf: allocation of {} bytes failed", csize);
    return 0;
  }
  // Go through xam's own setter: it sets base +2B48, cursor +2B4C = buf-4
  // (emission does +4 before each store), limit +2B50 and stride +2B58
  // together, and asserts the cursor is currently 0.
  uint64_t cargs[] = {dev, cbuf, csize / 4};
  kernel_state()->processor()->Execute(
      static_cast<xe::cpu::ThreadState*>(ts), GuideConst(0x81A01358u), cargs,
      xe::countof(cargs));
  // 81A042E0, the reservation that seeds the emitter's cursor, allocates from
  // [dev+0x30]/[dev+0x34] - a different pair from the block above, and the
  // fit test fails if they are not widened too.
  // Phase 813: by default this points the reservation window at the same
  // allocation as the command buffer, which is what made the command stream
  // unreadable (812). With guide_split_reserve_buf the reservation gets its
  // own buffer of the same size, so the two no longer overlap.
  uint32_t rbuf = cbuf;
  if (::cvars::guide_split_reserve_buf) {
    static uint32_t rb = 0;
    if (!rb) {
      rb = mem->SystemHeapAlloc(csize, 4096, kSystemHeapPhysical);
      if (rb) std::memset(mem->TranslateVirtual(rb), 0, csize);
    }
    if (rb) {
      rbuf = rb;
      XELOGI("GuideBindDeviceCmdbuf: split reserve buffer {:08X} (cmd {:08X})",
             rb, cbuf);
    } else {
      XELOGW("GuideBindDeviceCmdbuf: split reserve alloc failed; aliasing");
    }
  }
  xe::store_and_swap<uint32_t>(mem->TranslateVirtual(dev + 0x30u), rbuf);
  xe::store_and_swap<uint32_t>(mem->TranslateVirtual(dev + 0x34u),
                               rbuf + csize);
  // Phase 684: [+0x38] is the writer's safety limit, and xam's own installer
  // (81A018C8) derives it as end - 0xA0. Setting the pair without it left
  // 40870D00 with a limit still pointing into the device's old buffer while
  // begin/end pointed at ours - a triple that cannot be read consistently.
  xe::store_and_swap<uint32_t>(mem->TranslateVirtual(dev + 0x38u),
                               cbuf + csize - 0xA0u);
  // Phase 652: publish the buffer to guide_cmdbuf_base_. The second-context
  // path (guide_second_context_kb), which executes the Guide's emitted
  // packets directly via ExecuteGuestBufferUnsafe, is gated on that member -
  // and only the original draw-hook binder set it, on a hook that does not
  // fire in this configuration. Without this the whole ring question is
  // unavoidable; with it there is a submission route that needs no ring.
  guide_cmdbuf_base_ = cbuf;
  guide_cmdbuf_size_ = csize;
  XELOGI("GuideBindDeviceCmdbuf: dev={:08X} buf={:08X} +2B48={:08X} "
         "+2B4C={:08X} +2B50={:08X} [30]={:08X} [34]={:08X}",
         dev, cbuf, rdv(dev + 0x2B48u), rdv(dev + 0x2B4Cu),
         rdv(dev + 0x2B50u), rdv(dev + 0x30u), rdv(dev + 0x34u));
  return cbuf;
}

uint32_t XamProviderSlot() {
  if (g_provider_slot_done) {
    return g_provider_slot;
  }
  g_provider_slot_done = true;
  auto* mem = kernel_state() ? kernel_state()->memory() : nullptr;
  auto xam = kernel_state() ? kernel_state()->GetModule("xam.xex", true)
                            : nullptr;
  uint32_t xui_init = xam ? xam->GetProcAddressByOrdinal(0x340) : 0;
  if (!mem || !xui_init) {
    return 0;
  }
  uint32_t hi = 0, rt = 0, seen = 0;
  for (uint32_t off = 0; off < 0x400; off += 4) {
    uint32_t w =
        xe::load_and_swap<uint32_t>(mem->TranslateVirtual(xui_init + off));
    if ((w >> 26) == 15 && ((w >> 16) & 31) == 0) {
      hi = w & 0xFFFF;
      rt = (w >> 21) & 31;
    } else if (hi && (w >> 26) == 36 && ((w >> 16) & 31) == rt) {
      int32_t lo = static_cast<int16_t>(w & 0xFFFF);
      uint32_t slot = (hi << 16) + lo;
      if (++seen == 2) {
        g_provider_slot = slot;
        XELOGI("XamProviderSlot: XuiInit {:08X} store #2 -> slot {:08X}",
               xui_init, slot);
        return g_provider_slot;
      }
    }
  }
  XELOGW("XamProviderSlot: not resolved on this build");
  return 0;
}

uint32_t XamXuiCtxSlot() {
  if (g_xui_ctx_slot_done) {
    return g_xui_ctx_slot;
  }
  g_xui_ctx_slot_done = true;
  auto* mem = kernel_state() ? kernel_state()->memory() : nullptr;
  uint32_t host = XamRenderHost();
  auto xam = kernel_state() ? kernel_state()->GetModule("xam.xex", true)
                            : nullptr;
  uint32_t xui_init = xam ? xam->GetProcAddressByOrdinal(0x340) : 0;
  if (!mem || !host || !xui_init) {
    XELOGW("XamXuiCtxSlot: need render host and XuiInit; have {:08X}/{:08X}",
           host, xui_init);
    return 0;
  }
  // Walk the host's calls; remember the previous one; stop at XuiInit.
  uint32_t prev = 0;
  for (uint32_t off = 0; off < 0x200; off += 4) {
    uint32_t w = xe::load_and_swap<uint32_t>(mem->TranslateVirtual(host + off));
    if ((w >> 26) != 18 || !(w & 1)) continue;
    int32_t li = (w >> 2) & 0xFFFFFF;
    if (li & 0x800000) li -= 0x1000000;
    uint32_t tgt = host + off + (li << 2);
    if (tgt == xui_init) {
      if (!prev) break;
      g_xui_createdc = prev;
      // First lis/lwz global read inside that helper is the slot.
      uint32_t hi = 0, rt = 0;
      for (uint32_t o2 = 0; o2 < 0x80; o2 += 4) {
        uint32_t v =
            xe::load_and_swap<uint32_t>(mem->TranslateVirtual(prev + o2));
        if ((v >> 26) == 15 && ((v >> 16) & 31) == 0) {
          hi = v & 0xFFFF;
          rt = (v >> 21) & 31;
        } else if (hi && (v >> 26) == 32 && ((v >> 16) & 31) == rt) {
          int32_t lo = static_cast<int16_t>(v & 0xFFFF);
          g_xui_ctx_slot = (hi << 16) + lo;
          XELOGI("XamXuiCtxSlot: helper {:08X} -> slot {:08X}", prev,
                 g_xui_ctx_slot);
          return g_xui_ctx_slot;
        }
      }
      break;
    }
    prev = tgt;
  }
  XELOGW("XamXuiCtxSlot: not resolved on this build");
  return 0;
}

uint32_t XamRenderHost() {
  if (g_render_host_done) {
    return g_render_host;
  }
  g_render_host_done = true;
  auto* mem = kernel_state() ? kernel_state()->memory() : nullptr;
  if (!mem || !g_xam_lo) {
    return 0;
  }
  for (uint32_t a = g_xam_lo; a + 48 <= g_xam_hi; a += 4) {
    uint32_t w[12];
    for (int k = 0; k < 12; ++k) {
      w[k] = xe::load_and_swap<uint32_t>(mem->TranslateVirtual(a + k * 4));
    }
    if (w[0] != 0x7D8802A6u || w[1] != 0x9181FFF8u || w[2] != 0xFBE1FFF0u) {
      continue;
    }
    if ((w[3] >> 26) != 37 || (w[3] & 0xFFFF) != 0xFF10u) {
      continue;  // stwu r1,-240(r1)
    }
    for (int j = 4; j < 10; ++j) {
      if (w[j] == 0x38A00078u && w[j + 1] == 0x38800000u &&
          (w[j + 2] & 0xFFFF0000u) == 0x38610000u &&
          (w[j + 2] & 0xFFFFu) == 100u) {
        g_render_host = a;
        XELOGI("XamRenderHost: located at {:08X}", a);
        return g_render_host;
      }
    }
  }
  XELOGW("XamRenderHost: not found in this xam image");
  return 0;
}

uint32_t XamDeviceSlot() {
  if (g_xam_dev_slot_done) {
    return g_xam_dev_slot;
  }
  g_xam_dev_slot_done = true;
  auto* mem = kernel_state() ? kernel_state()->memory() : nullptr;
  if (!mem || !g_xam_lo) {
    return 0;
  }
  // lis rX,0x815F / lwz rX,imm(rX) / lwz rX,0(rX) / rlwinm rX,rX,0,22,22
  for (uint32_t a = g_xam_lo; a + 0x60 <= g_xam_hi; a += 4) {
    uint32_t w0 = xe::load_and_swap<uint32_t>(mem->TranslateVirtual(a + 0x0C));
    if ((w0 >> 26) != 15 || ((w0 >> 16) & 31) != 0 || (w0 & 0xFFFF) != 0x815F) {
      continue;
    }
    uint32_t w3 = xe::load_and_swap<uint32_t>(mem->TranslateVirtual(a + 0x18));
    if ((w3 >> 26) != 21 || ((w3 >> 11) & 31) != 0 || ((w3 >> 6) & 31) != 22 ||
        ((w3 >> 1) & 31) != 22) {
      continue;  // not the rlwinm rX,rX,0,22,22 bit-0x200 test
    }
    uint32_t hi = xe::load_and_swap<uint32_t>(mem->TranslateVirtual(a + 0x54));
    uint32_t lo = xe::load_and_swap<uint32_t>(mem->TranslateVirtual(a + 0x58));
    if ((hi >> 26) == 15 && (lo >> 26) == 14) {
      g_xam_dev_slot = ((hi & 0xFFFF) << 16) + (lo & 0xFFFF);
      XELOGI("XamDeviceSlot: creator at {:08X} -> slot {:08X}", a,
             g_xam_dev_slot);
      return g_xam_dev_slot;
    }
  }
  XELOGW("XamDeviceSlot: device creator not found in this xam image");
  return 0;
}

uint32_t XamUiThreadSlot() {
  if (g_ui_thread_slot_done) {
    return g_ui_thread_slot;
  }
  g_ui_thread_slot_done = true;
  auto* mem = kernel_state() ? kernel_state()->memory() : nullptr;
  if (!mem || !g_xam_lo) {
    return 0;
  }
  for (uint32_t a = g_xam_lo; a + 32 <= g_xam_hi; a += 4) {
    uint32_t w[8];
    for (int k = 0; k < 8; ++k) {
      w[k] = xe::load_and_swap<uint32_t>(mem->TranslateVirtual(a + k * 4));
    }
    bool cur = false, clz = false, norm = false;
    for (int k = 0; k < 8; ++k) {
      if (k < 3 && (w[k] >> 26) == 32 && ((w[k] >> 16) & 31) == 13 &&
          (w[k] & 0xFFFF) == 256) {
        cur = true;
      }
      if ((w[k] >> 26) == 31 && ((w[k] >> 1) & 0x3FF) == 26) clz = true;
      if ((w[k] >> 26) == 21 && ((w[k] >> 11) & 31) == 27 &&
          ((w[k] >> 6) & 31) == 31 && ((w[k] >> 1) & 31) == 31) {
        norm = true;
      }
    }
    if (!cur || !clz || !norm) continue;
    uint32_t hi = 0, lo1 = 0, lo2 = 0;
    bool hi_ok = false, lo1_ok = false, lo2_ok = false;
    for (int k = 0; k < 8; ++k) {
      if ((w[k] >> 26) == 15 && ((w[k] >> 16) & 31) == 0 && !hi_ok) {
        hi = w[k] & 0xFFFF;
        hi_ok = true;
      } else if ((w[k] >> 26) == 14 && hi_ok && !lo1_ok) {
        lo1 = w[k] & 0xFFFF;
        lo1_ok = true;
      } else if ((w[k] >> 26) == 32 && ((w[k] >> 16) & 31) != 13 && !lo2_ok) {
        lo2 = w[k] & 0xFFFF;
        lo2_ok = true;
      }
    }
    if (hi_ok && lo1_ok && lo2_ok) {
      g_ui_thread_slot = (hi << 16) + lo1 + lo2;
      XELOGI("XamUiThreadSlot: identity check at {:08X} -> slot {:08X}", a,
             g_ui_thread_slot);
      return g_ui_thread_slot;
    }
  }
  XELOGW("XamUiThreadSlot: identity check not found in this xam image");
  return 0;
}

void SetGuideDrawHook(uint32_t fn, uint32_t self) {
  guide_draw_fn_ = fn;
  guide_draw_this_ = self;
}

static void RegisterGraphicsNotification(uint32_t callback, uint32_t context,
                                         bool is_xam) {
  auto global_lock = graphics_notification_region_.Acquire();
  if (!graphics_notification_routines_) {
    graphics_notification_routines_ =
        new std::vector<GraphicsNotificationRoutine>();
  }
  if (!callback) {
    return;
  }
  for (auto& r : *graphics_notification_routines_) {
    if (r.callback == callback && r.context == context) {
      return;
    }
  }
  graphics_notification_routines_->push_back({callback, context, is_xam});
  XELOGI("Vd{}RegisterGraphicsNotification: callback {:08X} context {:08X}",
         is_xam ? "Xam" : "", callback, context);
}

dword_result_t VdRegisterGraphicsNotification_entry(dword_t callback,
                                                    dword_t context,
                                                    dword_t unk2) {
  RegisterGraphicsNotification(callback, context, false);
  return 0;
}
DECLARE_XBOXKRNL_EXPORT1(VdRegisterGraphicsNotification, kVideo, kImplemented);

dword_result_t VdRegisterXamGraphicsNotification_entry(dword_t callback,
                                                       dword_t context,
                                                       dword_t unk2) {
  RegisterGraphicsNotification(callback, context, true);
  return 0;
}
DECLARE_XBOXKRNL_EXPORT1(VdRegisterXamGraphicsNotification, kVideo,
                         kImplemented);

dword_result_t VdCallGraphicsNotificationRoutines_entry(
    unknown_t unk0, pointer_t<BufferScaling> args_ptr) {
  assert_true(unk0 == 1);
  {
    static std::atomic<uint32_t> gcalls{0};
    uint32_t n = ++gcalls;
    if (n <= 3 || (n % 300) == 0) {
      XELOGI("VdCallGraphicsNotificationRoutines #{} (hook={:08X})", n,
             guide_draw_fn_);
    }
  }

  // Callbacks get 0, r3, r4 (per the original TODO here).
  std::vector<GraphicsNotificationRoutine> routines;
  {
    auto global_lock = graphics_notification_region_.Acquire();
    if (graphics_notification_routines_) {
      routines = *graphics_notification_routines_;
    }
  }
  auto* thread = XThread::GetCurrentThread();
  if (!thread) {
    return 0;
  }
  // The Guide draws here, on the title's render thread, inside the title's
  // frame - the only place the title's thread-affine D3D device may be used.
  if (guide_draw_fn_ && guide_draw_this_) {
    uint64_t gargs[] = {guide_draw_this_};
    kernel_state()->processor()->Execute(thread->thread_state(),
                                         guide_draw_fn_, gargs,
                                         xe::countof(gargs));
  }
  if (routines.empty()) {
    return 0;
  }
  for (auto& r : routines) {
    uint64_t args[] = {0, static_cast<uint32_t>(unk0),
                       args_ptr.guest_address()};
    kernel_state()->processor()->Execute(thread->thread_state(), r.callback,
                                         args, xe::countof(args));
  }
  return 0;
}
DECLARE_XBOXKRNL_EXPORT2(VdCallGraphicsNotificationRoutines, kVideo,
                         kImplemented, kSketchy);

