            XELOGI("Guide pre-draw: wrapper={:08X} dev={:08X} [32A0]={:08X} "
                   "[32B0]={:08X} [3F74]={:08X}",
                   pwrap, pdev, prd(pdev + 0x32A0u), prd(pdev + 0x32B0u),
                   prd(pdev + 0x3F74u));
